using Microsoft.AspNetCore.Authentication.Certificate;
using Microsoft.AspNetCore.Server.Kestrel.Https;
using MtlsRotationServer.Certificates;
using System.Security.Claims;
using System.Security.Cryptography.X509Certificates;

var builder = WebApplication.CreateBuilder(args);

// Certs are generated by scripts/generate-certs.ps1 and copied to output (Resources/Certificates).
// Server keeps only public material (.crt): public key + metadata, no private key, no password.
// - ca.crt: trust anchor — the whole client certificate chain must chain to this CA (Certificate Authority).
// - client-*.crt: allowlist of accepted clients. What is check is a project choice:
//   In this example SHA-256 fingerprint match + not expired.

var certsDir = Path.Combine(AppContext.BaseDirectory, "Resources", "Certificates");

var caPath = Path.Combine(certsDir, "ca.crt");
if (!File.Exists(caPath))
{
    throw new InvalidOperationException(
        "Demo CA certificate is missing. Run .\\scripts\\generate-certs.ps1 first " +
        $"(expected: {caPath}).");
}

var clientCertificatePaths = Directory.GetFiles(certsDir, "client-*.crt");
if (clientCertificatePaths.Length == 0)
{
    throw new InvalidOperationException(
        "No client certificates were found. Run .\\scripts\\generate-certs.ps1 first " +
        $"(expected: {certsDir}\\client-*.crt).");
}

var trustedClientCertificates = new TrustedClientCertificates(clientCertificatePaths);
builder.Services.AddSingleton(trustedClientCertificates);
builder.Services.AddSingleton<CertificateValidation>();

builder.WebHost.ConfigureKestrel(options =>
{
    options.ConfigureHttpsDefaults(httpsOptions =>
    {
        httpsOptions.ClientCertificateMode = ClientCertificateMode.RequireCertificate;
        // Project policy: fingerprint on allowlist + NotAfter in the future.
        // Chain trust is enforced in Certificate Authentication below.
        httpsOptions.ClientCertificateValidation = (certificate, _, _) =>
        {
            var entry = trustedClientCertificates.Find(certificate);
            return entry is not null && entry.NotAfter > DateTimeOffset.UtcNow;
        };
    });
});

builder.Services
    .AddAuthentication(CertificateAuthenticationDefaults.AuthenticationScheme)
    .AddCertificate(options =>
    {
        options.AllowedCertificateTypes = CertificateTypes.All;
        options.RevocationMode = X509RevocationMode.NoCheck;
        // Require the client cert chain to be trusted via our demo CA.
        options.ChainTrustValidationMode = X509ChainTrustMode.CustomRootTrust;
        options.CustomTrustStore.Add(X509CertificateLoader.LoadCertificateFromFile(caPath));

        options.Events = new CertificateAuthenticationEvents
        {
            OnCertificateValidated = context =>
            {
                var validation = context.HttpContext.RequestServices.GetRequiredService<CertificateValidation>();
                if (!validation.IsAllowed(context.ClientCertificate, out var entry) || entry is null)
                {
                    context.Fail("Client certificate was rejected by the trusted client certificates.");
                    return Task.CompletedTask;
                }

                var fingerprint = CertificateValidation.GetFingerprint(context.ClientCertificate);
                context.Principal = validation.CreatePrincipal(entry, fingerprint);
                context.Success();
                return Task.CompletedTask;
            }
        };
    });

builder.Services.AddAuthorization();

var app = builder.Build();

app.UseAuthentication();
app.UseAuthorization();

app.MapGet("/invoices", (ClaimsPrincipal user) =>
    {
        var clientId = user.FindFirstValue(CertificateValidation.ClientIdClaimType)
            ?? user.FindFirstValue(ClaimTypes.NameIdentifier);

        return Results.Ok(new
        {
            clientId,
            invoices = new[]
            {
                new { id = "INV-1001", amount = 1200.00m, currency = "PLN" },
                new { id = "INV-1002", amount = 450.50m, currency = "PLN" }
            }
        });
    })
    .RequireAuthorization();

app.MapGet("/mtls/check", (ClaimsPrincipal user) =>
    {
        var clientId = user.FindFirstValue(CertificateValidation.ClientIdClaimType)
            ?? user.FindFirstValue(ClaimTypes.NameIdentifier);
        var fingerprint = user.FindFirstValue(CertificateValidation.FingerprintClaimType);
        var notAfterRaw = user.FindFirstValue("not_after");

        DateTimeOffset? notAfter = DateTimeOffset.TryParse(notAfterRaw, out var parsed)
            ? parsed
            : null;

        return Results.Ok(new
        {
            clientId,
            fingerprintSha256 = fingerprint,
            notAfter
        });
    })
    .RequireAuthorization();

app.Run();